import os, sys, math, random
sys.path.insert(0, '/home/imnyj/Workspace/paper4/coder')
os.chdir('/home/imnyj/Workspace/paper4/coder')
import numpy as np
import src.hot_swap_trainer as H
import src.rl_interface as R

MODE = sys.argv[1] if len(sys.argv)>1 else "rand"
env = H.AoiV2IEnv(density=25.0, seed=42, max_steps=600, warmup_steps=350)
obs, info = env.reset()
dec = env.decoder
rng = random.Random(0)

def make(vid):
    if MODE=="rand":
        return (dec.delta_from_unit(rng.random()), rng.randrange(4), rng.uniform(dec.p_min,dec.p_max))
    if MODE=="fast":   # everyone at Delta=0.1s, max power, channel 0..3
        return (dec.delta_min, rng.randrange(4), dec.p_max)
    if MODE=="fast1ch":
        return (dec.delta_min, 0, dec.p_max)
    raise SystemExit

action_dict = {vid: make(vid) for vid in obs}
vecs=[]; cbrs=[]; subcbr=[]
for t in range(600):
    obs, rew, term, trunc, inf = env.step(action_dict)
    for vid in obs: vecs.append(np.asarray(obs[vid],dtype=np.float32).copy())
    cbrs.append(inf["cbr"]); subcbr.append(max(inf["subchannel_cbr"]))
    action_dict = {vid: make(vid) for vid in inf["needs_decision"]}
V=np.array(vecs)
names=["0 last_pred_err","1 vx","2 vy","3 speed","4 accel","5 dx","6 dy","7 dist","8 red","9 yel","10 grn","11 t_switch","12 d_stop","13 n_active","14 cbr","15 n_queue","16 heading"]
print("MODE",MODE,"samples",V.shape)
for i,n in enumerate(names):
    c=V[:,i]; print(f"{n:18s} uniq={len(np.unique(np.round(c,6))):6d} min={c.min():8.4f} max={c.max():8.4f} mean={c.mean():8.4f} std={c.std():8.4f}")
print("cbr mean %.5f max %.5f | max subch cbr %.5f"%(np.mean(cbrs),np.max(cbrs),np.max(subcbr)))
m=env.get_metrics()
for k in sorted(m): print("  ",k,m[k])
